# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MED KAVRAMI VE MED HARFLERİ (حُرُوفُ الْمَدِّ — ا ، و ، ي)</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="127" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">1. Med Harfi: ELİF (ا)</text>\n  <text x="127" y="108" text-anchor="middle" font-size="11" fill="#1e3a8a">Hareketsiz (sâkin) gelir,</text>\n  <text x="127" y="126" text-anchor="middle" font-size="11" fill="#1e3a8a">önündeki harf ÜSTÜN olur.</text>\n  <text x="127" y="160" text-anchor="middle" font-size="18" font-weight="bold" fill="#1d4ed8">قَالَ · كَانَ · مَالِكِ</text>\n  <text x="127" y="190" text-anchor="middle" font-size="11" fill="#475569">(Kâle · Kâne · Mâliki)</text>\n  <text x="127" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">«a / â» sesiyle uzatır</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">2. Med Harfi: VAV (و)</text>\n  <text x="350" y="108" text-anchor="middle" font-size="11" fill="#14532d">Hareketsiz (sâkin) gelir,</text>\n  <text x="350" y="126" text-anchor="middle" font-size="11" fill="#14532d">önündeki harf ÖTRE olur.</text>\n  <text x="350" y="160" text-anchor="middle" font-size="18" font-weight="bold" fill="#15803d">يَقُولُ · نُورٌ · غَفُورٌ</text>\n  <text x="350" y="190" text-anchor="middle" font-size="11" fill="#475569">(Yekûlü · Nûrun · Gafûrun)</text>\n  <text x="350" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">«u / û» sesiyle uzatır</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="572" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#a16207">3. Med Harfi: YA (ي)</text>\n  <text x="572" y="108" text-anchor="middle" font-size="11" fill="#713f12">Hareketsiz (sâkin) gelir,</text>\n  <text x="572" y="126" text-anchor="middle" font-size="11" fill="#713f12">önündeki harf ESRE olur.</text>\n  <text x="572" y="160" text-anchor="middle" font-size="18" font-weight="bold" fill="#a16207">قِيلَ · دِينِ · سَمِيعٌ</text>\n  <text x="572" y="190" text-anchor="middle" font-size="11" fill="#475569">(Kîle · Dîni · Semîun)</text>\n  <text x="572" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">«i / î» sesiyle uzatır</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MED ÇEŞİTLERİ: ASLİ MED (MEDD-İ TABİÎ) VE FER\'İ MEDDE GİRİŞ</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#0e7490">Asli Med (Medd-i Tabiî / Doğal Med)</text>\n  <text x="180" y="108" text-anchor="middle" font-size="11" fill="#164e63">• Med harfinden (ا، و، ي) sonra</text>\n  <text x="180" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#164e63">med sebebi (hemze veya sükûn) YOKTUR.</text>\n  <text x="180" y="152" text-anchor="middle" font-size="11" fill="#164e63">• Uzatma miktarı: 1 Elif miktarıdır.</text>\n  <text x="180" y="182" text-anchor="middle" font-size="15" font-weight="bold" fill="#0891b2">نُوحِيهَا (Nû - hî - hâ)</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11" fill="#475569">Üç med harfini bir arada içeren örnek kelime</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#7e22ce">Fer\'i Med (Birincil Olmayan Med)</text>\n  <text x="520" y="108" text-anchor="middle" font-size="11" fill="#581c87">• Med harfinden sonra bir «Med Sebebi»</text>\n  <text x="520" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">(Hemze «ء» veya Sükûn «ْ / ّ») gelir.</text>\n  <text x="520" y="152" text-anchor="middle" font-size="11" fill="#581c87">• 1 elif miktarından daha fazla uzatılır.</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11" fill="#334155">Başlıca Türleri: Medd-i Muttasıl, Medd-i Munfasıl,</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#334155">Medd-i Lâzım, Medd-i Ârız, Medd-i Lîn</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SALLİ VE BARİK DUALARINDA TECVİT VE MED UYGULAMASI</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Allahümme Salli Duasından Örnekler</text>\n  <text x="180" y="110" text-anchor="middle" font-size="14" font-weight="bold" fill="#9a3412">اَللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#7c2d12">• اَللّٰهُمَّ ve عَلٰى: Çeker (mukadder elif) ile</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#7c2d12">1 elif miktarı Medd-i Tabiî yapılır.</text>\n  <text x="180" y="184" text-anchor="middle" font-size="14" font-weight="bold" fill="#9a3412">كَمَا صَلَّيْتَ · إِبْرَاهِيمَ · حَمِيدٌ مَجِيدٌ</text>\n  <text x="180" y="210" text-anchor="middle" font-size="11" fill="#475569">كَمَا (Elif), إِبْرَاهِيمَ ve حَمِيدٌ (Ya) med harfleridir.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Allahümme Barik Duasından Örnekler</text>\n  <text x="520" y="110" text-anchor="middle" font-size="14" font-weight="bold" fill="#831843">اَللّٰهُمَّ بَارِكْ عَلٰى مُحَمَّدٍ</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#831843">• بَارِكْ (Bârik): ب harfinden sonra gelen</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#831843">sâkin Elif (ا) ile Medd-i Tabiî yapılır.</text>\n  <text x="520" y="184" text-anchor="middle" font-size="14" font-weight="bold" fill="#831843">كَمَا بَارَكْتَ عَلٰى إِبْرَاهِيمَ</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" fill="#475569">بَارَكْتَ kelimesinde بَا hecesi 1 elif uzatılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
